        if (process.platform === "win32") {
          await exec(`attrib +h "${realDirPathInMdz}"`);
        }
        let fileContent = await fs.promises.readFile(realFilePathInMdz, "utf8");
        setOpenedFileHistory(sqliteMan, fileName, filePath, getNow());
