const Sqlite3 = require(path.join(__dirname, `..${path.sep}..${path.sep}node_modules${path.sep}better-sqlite3`));
let main;
let globalFilePath;
if (process.platform === "darwin") {
  electron.app.on("open-file", (event, filePath) => {
    event.preventDefault();
    if (main && main.webContents) {
      main.webContents.send("default-open-file", filePath);
    } else {
      globalFilePath = filePath;
    }
  });
}
electron.app.whenReady().then(() => {
  let settings_dir_path = path.join(electron.app.getPath("appData"), ".ame_conf");
  try {
    const stats = fs.statSync(settings_dir_path);
    if (!stats.isDirectory()) {
      electron.dialog.showMessageBox({
        type: "error",
        // 图标类型: info, error, question, none
        title: "AME启动出错",
        message: `路径“${electron.app.getPath("appData")}”内有“.ame_conf”文件残留，请将它删除，否则AME无法启动！`,
        // 主内容
        buttons: ["退出AME"]
        // 按钮文字数组
      }).then((result) => {
        if (result.response === 0) {
          electron.app.quit();
        }
      });
    }
  } catch (e) {
    fs.mkdirSync(settings_dir_path, { recursive: true });
  }
  menu();
  ipc(Sqlite3, path.join(settings_dir_path, "ame.sqlite"));
  let args = process.argv;
  for (let i = 0; i < args.length; i++) {
    let arg = args[i];
    if (arg.indexOf("--direct-open-file=") !== -1) {
      globalFilePath = arg.replace("--direct-open-file=", "");
      break;
    }
  }
  main = mainWindow();
  main.webContents.on("did-finish-load", () => {
    if (globalFilePath) {
      main.webContents.send("default-open-file", globalFilePath);
      globalFilePath = null;
    }
  });
});
electron.app.on("window-all-closed", () => {
  electron.app.quit();
});
